-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.first_answers_since(since timestamp with time zone)
 RETURNS TABLE(note_guid text, ord smallint, first_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select l.note_guid, l.ord, min(l.reviewed_at)
    from public.review_log l
   where l.user_id = auth.uid() and l.rating is not null
   group by l.note_guid, l.ord
  having min(l.reviewed_at) >= since;
$function$;

grant execute on function public.first_answers_since(since timestamp with time zone) to authenticated;
grant execute on function public.first_answers_since(since timestamp with time zone) to service_role;
